// ─────────────────────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────────────────────

export type Job<TInput, TResult> = {
  id: string;
  input: TInput;
  executor: (input: TInput) => Promise<TResult>;
};

export type RetryOptions = {
  maxRetries?: number;
  baseDelayMs?: number;
  maxDelayMs?: number;
};

export type QueueOptions = {
  maxConcurrency: number;
  maxRequestsPerSecond: number;
  retry?: RetryOptions;
};

export type QueueResult<TResult> = {
  successes: number;
  failures: number;
  errors: Map<string, Error>;
  results: Map<string, TResult>;
};

// ─────────────────────────────────────────────────────────────────────────────
// Concurrency Semaphore
// ─────────────────────────────────────────────────────────────────────────────

class Semaphore {
  private count = 0;
  private readonly max: number;
  private readonly waiters: Array<{ resolve: () => void; reject: (e: any) => void }> = [];

  constructor(max: number) {
    this.max = max;
  }

  async acquire(signal?: AbortSignal): Promise<void> {
    if (signal?.aborted) throw signal.reason ?? new Error('Aborted');
    if (this.count < this.max) {
      this.count++;
      return;
    }

    return new Promise<void>((resolve, reject) => {
      const waiter = { resolve, reject };
      this.waiters.push(waiter);

      signal?.addEventListener('abort', () => {
        const idx = this.waiters.indexOf(waiter);
        if (idx !== -1) this.waiters.splice(idx, 1);
        reject(signal.reason ?? new Error('Aborted'));
      }, { once: true });
    });
  }

  release(): void {
    this.count--;
    if (this.waiters.length > 0) {
      const next = this.waiters.shift()!;
      // Temporarily allow the waiter to proceed
      this.count++;
      next.resolve();
    }
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Token Bucket Rate Limiter
// ─────────────────────────────────────────────────────────────────────────────

class TokenBucket {
  private tokens: number;
  private lastRefill: number;
  private readonly maxTokens: number;
  private readonly refillRate: number; // tokens per millisecond

  constructor(maxRequestsPerSecond: number) {
    this.maxTokens = maxRequestsPerSecond;
    this.tokens = maxRequestsPerSecond; // start full
    this.lastRefill = Date.now();
    this.refillRate = maxRequestsPerSecond / 1000;
  }

  async acquire(signal?: AbortSignal): Promise<void> {
    while (true) {
      this.refill();
      if (this.tokens >= 1) {
        this.tokens -= 1;
        return;
      }

      // Calculate exact wait time until 1 token is available
      const waitMs = (1 - this.tokens) / this.refillRate;
      await this.wait(Math.max(1, waitMs), signal);
    }
  }

  private refill(): void {
    const now = Date.now();
    const elapsed = now - this.lastRefill;
    this.tokens = Math.min(this.maxTokens, this.tokens + elapsed * this.refillRate);
    this.lastRefill = now;
  }

  private async wait(ms: number, signal?: AbortSignal): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      const timeout = setTimeout(resolve, ms);
      signal?.addEventListener('abort', () => {
