class TokenBucket {
  private tokens: number;
  private lastRefill: number;
  private waiters: Waiter[] = [];
  private timer: ReturnType<typeof setTimeout> | null = null;

  constructor(
    private readonly rate: number,
    private readonly capacity: number,
  ) {
    if (rate === Number.POSITIVE_INFINITY) {
      this.tokens = Number.POSITIVE_INFINITY;
      this.lastRefill = Date.now();
    } else {
      if (!Number.isFinite(rate) || rate <= 0) throw new RangeError('rate must be positive or Infinity');
      this.capacity = Math.max(1, capacity);
      this.tokens = this.capacity;
      this.lastRefill = Date.now();
    }
  }

  private refill(): void {
    if (this.rate === Number.POSITIVE_INFINITY) return;
    const now = Date.now();
    const elapsedSeconds = Math.max(0, (now - this.lastRefill) / 1000);
    this.tokens = Math.min(this.capacity, this.tokens + elapsedSeconds * this.rate);
    this.lastRefill = now;
  }

  acquire(signal?: AbortSignal): Promise<void> {
    if (signal?.aborted) return Promise.reject(abortError());
    if (this.rate === Number.POSITIVE_INFINITY) return Promise.resolve();

    this.refill();
    if (this.tokens >= 1) {
      this.tokens -= 1;
      return Promise.resolve();
    }

    return new Promise<void>((resolve, reject) => {
      const waiter: Waiter = {
        resolve,
        reject,
        signal,
        onAbort: () => this.rejectWaiter(waiter, abortError()),
        settled: false,
      };
      if (signal) signal.addEventListener('abort', waiter.onAbort, { once: true });
      this.waiters.push(waiter);
      this.schedule();
    });
  }

  private schedule(): void {
    if (this.timer || this.waiters.length === 0) return;
    this.refill();
    let delayMs: number;
    if (this.tokens >= 1) {
      delayMs = 0;
    } else {
      const missing = 1 - this.tokens;
      delayMs = Math.max(0, (missing / this.rate) * 1000);
    }
    this.timer = setTimeout(() => {
      this.timer = null;
      this.processWaiters();
    }, Math.ceil(delayMs));
  }

  private processWaiters(): void {
    this.refill();
    while (this.waiters.length > 0 && this.tokens >= 1) {
      const waiter = this.waiters.shift()!;
      if (waiter.settled) continue;
      this.tokens -= 1;
      this.settle(waiter, () => waiter.resolve());
    }
    if (this.waiters.length > 0) {
      this.schedule();
    }
  }

  private rejectWaiter(waiter: Waiter, error: Error): void {
    if (waiter.settled) return;
    const idx = this.waiters.indexOf(waiter);
    if (idx !== -1) this.waiters.splice(idx, 1);
    this.settle(waiter, () => waiter.reject(error));
    if (this.waiters.length === 0) {
      if (this.timer) { clearTimeout(this.timer); this.timer = null; }
    } else {
      // If a waiter was removed, the scheduled time may still be okay; no need to reschedule unless tokens available now? Could check.
      this.schedule();
    }
  }

  private settle(waiter: Waiter, action: () => void): void {
    if (waiter.settled) return;
    waiter.settled = true;
    if (waiter.signal) waiter.signal.removeEventListener('abort', waiter.onAbort);
    action();
  }
}
